import time
import threading

def task_func(delay_time: float = 1.0, num_threads: int = 5):
    if num_threads <= 0:
        return []

    messages = [None] * num_threads

    def worker(index):
        if delay_time > 0:
            time.sleep(delay_time)
        messages[index] = f"Delay in thread {index} completed"

    threads = []
    for i in range(num_threads):
        thread = threading.Thread(target=worker, args=(i,))
        threads.append(thread)
        thread.start()

    for thread in threads:
        thread.join()

    return messages
